      exportPanel.appendChild(fmtWrap);
      // Location section
      const locWrap = document.createElement('div');
      locWrap.style.cssText = 'padding:10px 0 6px 0;';
      const locTitle = document.createElement('div'); locTitle.style.cssText = 'font-size:13px; font-weight:600; margin-bottom:4px;';
      locTitle.textContent = this.t('highlights_export_location') || '选择位置';
      // Remove the first description paragraph; place the choose button here instead
      const locDefaultHint = document.createElement('div'); locDefaultHint.style.cssText = 'font-size:12px; opacity:0.7;';
      locDefaultHint.textContent = this.t('highlights_export_location_default') || '默认位置（下载到 “SmartHighlighter-Backup/Individual Export/” 文件夹）';
      locWrap.appendChild(locTitle);
      // Insert choose location button where the first paragraph was
