      const anchorElForPosition = (
        tooltipOrCallback && tooltipOrCallback.nodeType === 1 &&
        tooltipOrCallback.classList && tooltipOrCallback.classList.contains('highlight-tooltip')
      ) ? tooltipOrCallback : highlightElement;

      const rect = anchorElForPosition.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const pickerHeight = 420; // Increased for two-level UI

      // Check if called from permanent toolbar (callback function) or regular highlight (tooltip element)
      const isFromPermanentToolbar = typeof tooltipOrCallback === 'function';
      let left, top, positionBelow;

      // Create color picker with two-level structure
      const colorPicker = document.createElement('div');
      colorPicker.className = `highlight-color-picker ${this.darkModeEnabled ? 'dark-theme' : 'light-theme'}`;
      // Use the active color: if opened from the permanent toolbar, prefer currentBatchColor;
      // otherwise, prefer the highlight's own color, falling back to currentColor.
      const activeBorderColor = (isFromPermanentToolbar
        ? (this.currentBatchColor || this.currentColor)
        : ((highlightElement && (highlightElement.getAttribute('data-color') || '')) || this.currentColor)
      ) || '#667eea';


      colorPicker.style.cssText = `
      position: absolute !important;
      background: ${this.darkModeEnabled ? '#2a2a2a' : '#ffffff'} !important;
      border-radius: var(--border-radius, 12px) !important;
      box-shadow: 0 8px 32px rgba(0, 0, 0, ${this.darkModeEnabled ? '0.6' : '0.3'}) !important;
      max-height: ${pickerHeight}px !important;
      width: 480px !important;
      overflow: hidden !important;
      z-index: 10005 !important;
      opacity: 0 !important;
      transition: all 0.3s ease-out !important;
      border: 2px solid ${activeBorderColor} !important;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif !important;
    `;

