      snapLeft.textContent = '⬅️';
      try { snapLeft.addEventListener('mouseenter', () => { try { this._showGuideTemporarily && this._showGuideTemporarily('left', 2000); } catch (_) { } }); } catch (_) { }
      const snapRight = document.createElement('button');
      snapRight.className = 'annotation-snap-btn right';
      snapRight.title = this.t('snap_to_right_guide');
      snapRight.textContent = '➡️';
      try { snapRight.addEventListener('mouseenter', () => { try { this._showGuideTemporarily && this._showGuideTemporarily('right', 2000); } catch (_) { } }); } catch (_) { }
      const delBtn = document.createElement('button');
      delBtn.className = 'annotation-delete-btn';
      delBtn.title = this.t('delete_annotation');
