          const currentTop = (() => {
            const v = parseFloat(box.style.top);
            return Number.isFinite(v) ? v : initialTop;
          })();
          const offset = { x: currentLeft - toolbarRef.x, y: currentTop - toolbarRef.y };
          const existingRef = this._dynamicRefSystem.annotations.references.get(highlightId) || {};
