    t(key) {
      // Ensure i18n objects exist
      if (!this.i18n) {
        this.i18n = this.getFallbackTranslations();
      }
      if (!this.i18nEn) {
        this.i18nEn = this.getFallbackTranslations();
      }

      const candidates = this._resolveI18nKeyCandidates(key);
      for (const candidate of candidates) {
        const value = this.i18n[candidate] || this.i18nEn[candidate];
        if (value) return value;
      }
      return key;
    }

    _resolveI18nKeyCandidates(key) {
      const candidates = [];
      candidates.push(key);
      if (!key.startsWith('tool_') && !key.startsWith('color_')) {
        candidates.push(`tool_${key}`);
        candidates.push(`color_${key}`);
      }
      if (key.startsWith('Classic') || key.startsWith('Neon') || key.startsWith('Pastels') || key.startsWith('Premium') || key.startsWith('Cosmic') || key.startsWith('Nature') || key.startsWith('Fire') || key.startsWith('Cyber') || key.startsWith('Vintage') || key.startsWith('Magical')) {
        candidates.push(`color_${key.toLowerCase()}`);
      }
      if (key === 'Magic') {
        candidates.push('color_magical');
      }
      return candidates;
    }

    getCategoryIcon(categoryId) {
      const categoryIcons = {
        recent: '⭐',
        classic: '🖍️',
        rgb: '🎯',
        red: '🟥',
        orange: '🟧',
        yellow: '🟨',
        green: '🟩',
        blue: '🟦',
        purple: '🟪',
        other: '🎨'
      };
      return categoryIcons[categoryId] || '';
    }

    // ==================== PDF Support Methods ====================

    async initializePdfSupport() {
      console.log('[PDF Init] Starting PDF support initialization...');

      try {
        // Check if current page is a PDF
        this.isPdfPage = this.detectPdfPage();

        if (this.isPdfPage) {
          console.log('[PDF Init] PDF page detected');

          // For Chrome's built-in PDF viewer, show a helper button
          this.addPdfHelperButton();

          // On the built-in viewer page that only shows the helper button, do not inject plugin UI elements (guides/toolbar/etc.)
          // We stop here to avoid adding UI beyond the button.
          return;
        } else {
          console.log('[PDF Init] Not a PDF page, skipping PDF support initialization');
        }
      } catch (error) {
        console.error('[PDF Init] Failed to initialize PDF support:', error);
      }
    }

    detectPdfPage() {
      const url = window.location.href;
      const contentType = document.contentType || '';

      console.log('[PDF Detection] URL:', url);
      console.log('[PDF Detection] Content-Type:', contentType);
      console.log('[PDF Detection] Document title:', document.title);

      // Check each detection method individually for debugging
      const checks = {
        contentType: contentType.includes('application/pdf'),
        urlPdf: url.includes('.pdf'),
        embedPdf: !!document.querySelector('embed[type="application/pdf"]'),
        objectPdf: !!document.querySelector('object[type="application/pdf"]'),
        chromeExtension: window.location.protocol === 'chrome-extension:' && url.includes('pdf'),
        firefoxPdfJs: !!(document.querySelector('#viewer') && document.querySelector('#toolbarContainer')),
        arxivPdf: url.includes('arxiv.org/pdf/'),
        pdfQuery: url.includes('.pdf?'),
        titlePdf: document.title.toLowerCase().includes('.pdf'),
        // Additional Chrome PDF viewer detection
        chromeNativeViewer: document.body && document.body.style.margin === '0px' && url.endsWith('.pdf'),
        // Check for PDF plugin elements
        pdfPlugin: !!document.querySelector('embed[src*=".pdf"], object[data*=".pdf"]')
      };

      console.log('[PDF Detection] Individual checks:', checks);

      const isPdf = Object.values(checks).some(Boolean);
      console.log('[PDF Detection] Result:', isPdf);

      return isPdf;
    }

    async loadPdfHandler() {
      // PDFHandler is now loaded via content_scripts in manifest.json
      if (window.PDFHandler) {
        console.log('[PDF Init] PDFHandler is available');
        return;
      } else {
        console.error('[PDF Init] PDFHandler not available even though it should be loaded via content_scripts');
        throw new Error('PDFHandler not available');
      }
    }

