              tint = this.isPageDarkMode() ? 'rgba(16,16,16,0.4)' : 'rgba(255,255,255,0.34)';
              halo = this.hexToRgba(rainbowSolid(rbSeed), 0.58);
              outline = this.hexToRgba(rainbowSolid(rbSeed), 0.35);
              shadowPrimary = this.hexToRgba(rainbowSolid(rbSeed), 0.55);
