            const ambientShadow = this.isPageDarkMode() ? 'rgba(0,0,0,0.45)' : 'rgba(0,0,0,0.18)';
            const compositeShadow = `0 8px 20px ${ambientShadow}, 0 16px 36px ${shadowPrimary}`;
            element.style.boxShadow = compositeShadow;
