            const blurSpec = 'blur(6px) saturate(1.18)';
            element.style.backdropFilter = blurSpec;
            element.style.webkitBackdropFilter = blurSpec;
            element.style.textShadow = '0 0 3px rgba(255,255,255,0.35)';
