                  const w = Math.max(1, rect.width);
                  const h = Math.max(1, rect.height);
                  const diag = Math.sqrt(w * w + h * h);
                  // 指数型衰减：小框≈1，大框→0.35~0.5 区间
                  const att = Math.max(0.35, Math.min(1.0, Math.exp(- (diag / 360)) * 0.85 + 0.15));
