          rightText.setAttribute('y', String(centerY));
          rightText.setAttribute('dominant-baseline', 'middle');
          rightText.setAttribute('text-anchor', 'start');
          rightText.setAttribute('font-size', String(fontSize));
          rightText.setAttribute('font-weight', '700');
          rightText.setAttribute('stroke-linejoin', 'round');
