        const highlightEl = document.querySelector(`[data-highlight-id="${highlightId}"]`);
        if (!highlightEl) return;

        // Work relative to container (page wrapper) to keep embedding stable
        let container = meta.boxEl.offsetParent || meta.boxEl.parentElement || document.body;
        try { const cand = meta.boxEl.closest && meta.boxEl.closest('.pdf-page-wrapper'); if (cand) container = cand; } catch (_) { }
        const cRect = (container && container.getBoundingClientRect) ? container.getBoundingClientRect() : { left: 0, top: 0 };
        const hr = highlightEl.getBoundingClientRect();
        const containerViewportLeft = (cRect && Number.isFinite(cRect.left)) ? cRect.left : 0;
        const containerViewportTop = (cRect && Number.isFinite(cRect.top)) ? cRect.top : 0;
        const baseViewportLeftRel = hr.left - containerViewportLeft;
        const baseViewportTopRel = hr.top - containerViewportTop;
        const containerScrollLeft = Number.isFinite(container && container.scrollLeft) ? Number(container.scrollLeft || 0) : 0;
        const containerScrollTop = Number.isFinite(container && container.scrollTop) ? Number(container.scrollTop || 0) : 0;
        let scaleX = 1, scaleY = 1;
        try {
          const estimatedX = this._estimateCssToViewportScaleX(meta.boxEl, container, cRect);
          scaleX = Math.max(0.001, Number(estimatedX) || 1);
        } catch (_) { scaleX = 1; }
        try {
          const estimatedY = (typeof this._estimateCssToViewportScaleY === 'function')
            ? this._estimateCssToViewportScaleY(meta.boxEl, container, cRect)
            : this._estimateCssToViewportScaleX(meta.boxEl, container, cRect);
          scaleY = Math.max(0.001, Number(estimatedY) || 1);
        } catch (_) { scaleY = scaleX || 1; }

